FeatureScript 3112;
import(path : "onshape/std/geometry.fs", version : "3112.0");

// Fixture batch 166: boundary surfaces with end conditions on profiles of more than one edge. Generated by tools/fixtures/gen-batch-166.mjs; do not edit.
// Each case builds its geometry at the origin and may return a map of values to check.

function numbersProbe(numbers) returns array
{
    var out = [];
    for (var i = 0; i < size(numbers); i += 1)
        out = append(out, roundToPrecision(numbers[i], 9));
    return out;
}

// Each face's area, its point and normal at the middle of its parameters, and, for a B-spline surface, its degrees,
// knots, weights and poles (rounded to 1e-6 mm).
function surfaceProbe(context is Context, faces is Query) returns array
{
    var out = [];
    const r = function(x) { return roundToPrecision(x, 6); };
    for (var f in evaluateQuery(context, faces))
    {
        const p = evFaceTangentPlane(context, { "face" : f, "parameter" : vector(0.5, 0.5) });
        var entry = { "area" : r(evArea(context, { "entities" : f }) / millimeter ^ 2),
                "middle" : [r(p.origin[0] / millimeter), r(p.origin[1] / millimeter), r(p.origin[2] / millimeter)],
                "normal" : [r(p.normal[0]), r(p.normal[1]), r(p.normal[2])] };
        const s = evSurfaceDefinition(context, { "face" : f });
        entry["type"] = s.surfaceType;
        if (s is BSplineSurface)
        {
            entry.degrees = [s.uDegree, s.vDegree];
            entry.uKnots = numbersProbe(s.uKnots);
            entry.vKnots = numbersProbe(s.vKnots);
            if (s.isRational)
                entry.weights = s.weights;
            var rows = [];
            for (var i = 0; i < size(s.controlPoints); i += 1)
            {
                var points = [];
                for (var j = 0; j < size(s.controlPoints[i]); j += 1)
                {
                    const q = s.controlPoints[i][j];
                    points = append(points, [r(q[0] / millimeter), r(q[1] / millimeter), r(q[2] / millimeter)]);
                }
                rows = append(rows, points);
            }
            entry.poles = rows;
        }
        out = append(out, entry);
    }
    return out;
}

// boundary-surface: from a level sheet's edge in two pieces, matching it, to a line 10 across and 5 up
export function c001(context is Context, id is Id)
{
    const aSketch = newSketchOnPlane(context, id + "aSketch", { "sketchPlane" : plane(vector(0, 0, 0) * millimeter, vector(-1, 0, 0), vector(0, 1, 0)) });
    skLineSegment(aSketch, "l1", { "start" : vector(0, 0) * millimeter, "end" : vector(10, 0) * millimeter });
    skLineSegment(aSketch, "l2", { "start" : vector(10, 0) * millimeter, "end" : vector(20, 0) * millimeter });
    skSolve(aSketch);
    extrude(context, id + "a", { "bodyType" : ExtendedToolBodyType.SURFACE, "surfaceEntities" : qOwnedByBody(qBodyType(qCreatedBy(id + "aSketch", EntityType.BODY), BodyType.WIRE), EntityType.EDGE), "endBound" : BoundingType.BLIND, "depth" : 20 * millimeter });
    const t = newSketchOnPlane(context, id + "t", { "sketchPlane" : plane(vector(10, 0, 0) * millimeter, vector(1, 0, 0), vector(0, 1, 0)) });
    skLineSegment(t, "l1", { "start" : vector(0, 5) * millimeter, "end" : vector(20, 5) * millimeter });
    skSolve(t);
    boundarySurface(context, id + "surface1", { "uProfilesArray" : [{ "uProfileEntities" : qUnion([qContainsPoint(qOwnedByBody(qBodyType(qCreatedBy(id + "a", EntityType.BODY), BodyType.SHEET), EntityType.EDGE), vector(0, 5, 0) * millimeter), qContainsPoint(qOwnedByBody(qBodyType(qCreatedBy(id + "a", EntityType.BODY), BodyType.SHEET), EntityType.EDGE), vector(0, 15, 0) * millimeter)]), "uCondition" : BSurfEndDerivativeType.MATCH_TANGENT, "uMagnitude" : 1, "uReference" : qNothing(), "uDirection" : qNothing() }, { "uProfileEntities" : qOwnedByBody(qBodyType(qCreatedBy(id + "t", EntityType.BODY), BodyType.WIRE), EntityType.EDGE), "uCondition" : BSurfEndDerivativeType.DEFAULT, "uMagnitude" : 1, "uReference" : qNothing(), "uDirection" : qNothing() }], "vProfilesArray" : [] });
    return { "faces" : surfaceProbe(context, qOwnedByBody(qBodyType(qCreatedBy(id + "surface1", EntityType.BODY), BodyType.SHEET), EntityType.FACE)) };
}

